// usecases/config/environment.go:850-852
autoSchemaEnabled := true
if v := os.Getenv("AUTOSCHEMA_ENABLED"); v != "" {
	autoSchemaEnabled = !(strings.ToLower(v) == "false")
}

// usecases/objects/auto_schema.go:119-127
if schemaClass == nil {
	// it returns the newly created class and version
	schemaClass, schemaVersion, err = m.createClass(ctx, principal, namespacing.StripOwnNamespace(principal, object.Class), properties)
	if err != nil {
		return 0, fmt.Errorf("auto-schema: create collection: %w", err)
	}
	classes[object.Class] = versioned.Class{Class: schemaClass, Version: schemaVersion}
	classcache.RemoveClassFromContext(ctx, object.Class)
}

// usecases/objects/batch_add.go:197
schemaVersion, err := b.autoSchemaManager.autoSchema(ctx, principal, true, fetchedClasses, obj)

// usecases/objects/add.go:97
autoSchemaVersion, err := m.autoSchemaManager.autoSchema(ctx, principal, true, fetchedClasses, object)

